import{_ as l,o as r,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Infernalis (Day 1) -- OSD: Erasure Coding Pool Overwrite Support","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- OSD: Erasure Coding Pool Overwrite Support","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Erasure Coding","Ceph","RBD","两阶段提交","数据一致性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Erasure_Coding_Pool_Overwrite_Support.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Erasure_Coding_Pool_Overwrite_Support.md","lastUpdated":1780459816000}'),t={name:"posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Erasure_Coding_Pool_Overwrite_Support.md"};function _(s,i,a,n,p,u){return r(),e("div",null,[...i[0]||(i[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Erasure Coding (EC) 池覆盖支持讨论</p><p><strong>会议时间</strong>： CDS Infernalis 会议第二天</p><p><strong>参会人员</strong>： 多位 Ceph 开发者</p><p><strong>会议内容</strong>：</p><p><strong>主要议题</strong>：</p><ul><li>讨论了在 Erasure Coding (EC) 池中实现覆盖支持的可能性，尤其是针对 Rados Block Device (RBD) 的应用。</li><li>分析了不同实现方案的优缺点，包括： <ul><li>回滚日志</li><li>两阶段提交</li><li>不支持覆盖</li><li>改进 RBD 数据布局</li><li>缓存层实现</li></ul></li></ul><p><strong>讨论结果</strong>：</p><ul><li>两阶段提交方案被认为具有确定性、可预测性和与 RAID 类似的行为，是一个值得尝试的方案。</li><li>回滚日志方案由于需要额外的写入操作，可能引入较大的延迟，因此被认为不如两阶段提交方案。</li><li>不支持覆盖被认为是最简单的方法，但可能无法满足某些应用的需求。</li><li>改进 RBD 数据布局和缓存层实现被认为是可行的方案，但需要进一步研究和评估。</li></ul><p><strong>行动计划</strong>：</p><ul><li>由参会者之一负责实现两阶段提交方案或原型。</li><li>进一步研究其他方案的可行性和实现细节。</li><li>在决定最终方案之前，进行更多的讨论和评估。</li></ul><p><strong>其他要点</strong>：</p><ul><li>实现覆盖支持需要修改 Ceph 的某些核心组件，例如 PG 信息和 OSD 类。</li><li>在实现覆盖支持之前，需要考虑数据一致性和可用性等问题。</li><li>需要评估不同方案的性能和可扩展性。</li></ul><p><strong>关键词</strong>：</p><ul><li>Erasure Coding (EC)</li><li>覆盖支持</li><li>Rados Block Device (RBD)</li><li>回滚日志</li><li>两阶段提交</li><li>PG 信息</li><li>OSD 类</li></ul>',15)])])}const D=l(t,[["render",_]]);export{g as __pageData,D as default};
